// Pruebas de lógica sin navegador. Uso: cd tests && node smoke.cjs
const fs=require('fs'),vm=require('vm'),assert=require('assert'),path=require('path');
// Nombres que no deben aparecer como autoría (codificados para no publicarlos en claro)
const NOMBRES_FUERA=new RegExp(Buffer.from('SmVpc3NvbnxPc29yaW8=','base64').toString(),'i');
const root=path.join(__dirname,'..');
const html=fs.readFileSync(path.join(root,'index.html'),'utf8');
const script=[...html.matchAll(/<script>([\s\S]*?)<\/script>/g)].map(m=>m[1]).find(x=>x.includes('const DATA=window.ATLAS_DATA'));assert.ok(script,'no se encontró el script principal');
const ids=[...html.matchAll(/id="([^"]+)"/g)].map(x=>x[1]);
const els=Object.fromEntries(ids.map(id=>[id,{id,value:'',innerHTML:'',textContent:'',classList:{toggle(){},add(){}},addEventListener(){},dataset:{},style:{},click(){}}]));
const document={getElementById(id){if(!els[id])throw Error('Unknown DOM id '+id);return els[id]},querySelectorAll(){return []},createElement(){return {click(){},set href(x){},set download(x){}}}};
const window={scrollTo(){}};const URL={createObjectURL(){return 'blob:fake'},revokeObjectURL(){}};const Blob=function(){};
const context=vm.createContext({document,window,URL,Blob,console,setTimeout:()=>0});
vm.runInContext(fs.readFileSync(path.join(root,'data','atlas-data.js'),'utf8'),context);
vm.runInContext(fs.readFileSync(path.join(root,'data','atlas-actos.js'),'utf8'),context);
for(const iso of ['IND','COL','IRL','GIN','ESP'])vm.runInContext(fs.readFileSync(path.join(root,'data','paises',iso+'.js'),'utf8'),context);
vm.runInContext(script,context,{timeout:10000});
const run=fn=>vm.runInContext(fn,context,{timeout:5000});
const search=q=>{els.q.value=q;run('filterMandates()');return els.mandBody.innerHTML.toLowerCase()};
const recover=q=>{els.recoverQuery.value=q;run('recoverDocument()');return els.recoverResult.innerHTML};
const TM=()=>els.pTemasChips.innerHTML+els.pTemasTabla.innerHTML;
let n=0;const t=(name,fn)=>{fn();n++};
t('catálogo completo vigente',()=>{assert.equal(run('D.length'),57);assert.equal(run('D.filter(x=>x.alcance==="Temático").length'),44);assert.equal(run('D.filter(x=>x.alcance==="País").length'),13)});
t('KPIs',()=>assert.ok(els.kpis.innerHTML.includes('57')));
t('todo mandato tiene acto de creación y titular',()=>assert.equal(run('D.filter(x=>!x.actos.some(a=>a.rol==="creación")).length'),0));
for(const [q,e] of [['tortura','tortura'],['desapariciones','desaparici'],['mercenarios','mercenari'],['enforced disappearance','desaparici'],['derecho al agua','agua'],['A/HRC/RES/54/26','afrodescendientes'],['Belarus','belar']]) t('búsqueda '+q,()=>assert.ok(search(q).includes(e),'falla '+q));
t('sin resultados',()=>assert.ok(search('zzzxwqnomatch').includes('sin coincidencias')));
t('filtro por año',()=>{els.q.value='';els.yearfrom.value='1980';els.yearto.value='1980';run('filterMandates()');assert.ok(els.mandBody.innerHTML.toLowerCase().includes('desaparici'));els.yearfrom.value='';els.yearto.value='';run('clearFilters()')});
t('recuperación 1980: texto leído en E/1980/13 pp. 180–181',()=>{const r=recover('E/CN.4/RES/20(XXXVI)');assert.ok(r.includes('E/1980/13')&&r.includes('180–181')&&r.includes('TEXTO LEÍDO'))});
t('recuperación 1980 con escritura libre',()=>assert.ok(recover('resolución 20 (XXXVI)').includes('E/1980/13')));
t('borrador L. → resolución adoptada',()=>assert.ok(recover('A/HRC/51/L.40').includes('A/HRC/RES/51/19')));
t('símbolo sin RES → resolución',()=>assert.ok(recover('A/HRC/54/26').includes('A/HRC/RES/54/26')));
t('ECOSOC, no Comisión (ejecuciones)',()=>{const r=recover('E/CN.4/1982/35');assert.ok(r.includes('E/RES/1982/35')&&r.includes('Consejo Económico y Social'))});
t('Comisión: E/CN.4/1991/42 → E/CN.4/RES/1991/42',()=>assert.ok(recover('E/CN.4/1991/42').includes('E/CN.4/RES/1991/42')));
t('PDF en español enlazado',()=>assert.ok(recover('A/HRC/RES/54/26').includes('-ES.pdf')));
t('resolución antigua sin PDF → informe de sesión con páginas',()=>{const r=recover('E/CN.4/RES/1985/33');assert.ok(r.includes('E/1985/22')&&r.includes('71–72'),'1985/33')});
t('resolución HRC temprana con PDF validado',()=>assert.ok(recover('A/HRC/RES/7/22').includes('ap.ohchr.org')));
t('todo símbolo del índice tiene ruta al texto',()=>assert.equal(run('Object.values(ACTOS).filter(x=>x.simbolo&&(!x.texto||!(x.texto.fuentes.length||x.texto.informe_sesion.length))).length'),0));
t('no inventa: símbolo ausente',()=>{const r=recover('A/HRC/RES/99/99');assert.ok(r.includes('No está en el índice local')&&!r.includes('LOCALIZADO EN EL ÍNDICE'))});
t('búsqueda por palabras en español',()=>assert.ok(recover('desaparecidos').includes('A/HRC/RES/')));
t('búsqueda guiada con alternativas',()=>{els.guiadaSel.value='tortura';els.guiadaPais.value='';run('guiada()');const r=els.mandBody.innerHTML.toLowerCase();assert.ok(r.includes('tortura')&&r.includes('detenci'))});
t('mecanismos conexos: 33 verificados',()=>{assert.equal(run('MEC.length'),33);assert.equal(run('MEC.filter(m=>m.estado==="VERIFICADO").length'),33);assert.ok(els.mecBody.innerHTML.includes('CERD')&&els.mecBody.innerHTML.includes('A/RES/2106(XX)'))});
t('tarjeta al compartir: el primer <title> del HTML crudo es el real y va antes de cualquier script (WhatsApp no ejecuta JS)',()=>{const i=html.indexOf('<title>'),j=html.indexOf('<script');assert.ok(i>0&&i<j,'el <title> real debe ir antes del primer <script>');assert.ok(html.slice(i,i+60).startsWith('<title>Atlas ONU'));const head=html.slice(0,html.indexOf('</head>'));for(const m of head.matchAll(/<script[^>]*>([\s\S]*?)<\/script>/g))assert.ok(!/<\/?(title|style)>/.test(m[1]),'un script del <head> no puede llevar <title> o <style> literales')});
t('panel de calidad',()=>{const ok=run('D.flatMap(x=>x.actos).filter(a=>/^VERIFICADO/.test(a.estado)).length'),tot=run('D.flatMap(x=>x.actos).length');assert.ok(els.calidad.innerHTML.includes(ok+' de '+tot))});
t('filtro de verificación',()=>{els.q.value='';els.verif.value='reservas';run('filterMandates()');const n=run('filtered.length');assert.ok(n>0&&n<57);els.verif.value='';run('filterMandates()')});
const smart=q=>{els.quick.value=q;run('smartRun()');return els.smartOut.innerHTML};
t('búsqueda inteligente: sinónimo ES («desaparecidos»)',()=>{const r=smart('desaparecidos');assert.ok(r.includes('Desapariciones Forzadas')&&r.includes('E/CN.4/RES/20(XXXVI)'))});
t('búsqueda inteligente: erratas («tortrua»)',()=>{const r=smart('tortrua');assert.ok(r.includes('Quisiste decir')&&r.includes('tortura')&&r.includes('Relator Especial sobre la tortura'))});
t('búsqueda inteligente: «comida» → derecho a la alimentación',()=>assert.ok(smart('comida').includes('alimentaci')));
t('búsqueda inteligente: «niños migrantes» → CRC y CMW',()=>{const r=smart('niños migrantes');assert.ok(r.includes('CRC')&&r.includes('CMW'))});
t('búsqueda inteligente: país por sinónimo («bielorrusia»)',()=>assert.ok(smart('bielorrusia').includes('Belar')));
t('búsqueda inteligente: símbolo sin duplicados',()=>{const r=smart('A/HRC/RES/54/26');assert.equal((r.match(/Ver texto y ruta/g)||[]).length,1)});
t('búsqueda inteligente: sigla corta no da falsos positivos («cat» ≠ «education»)',()=>{const r=smart('cat');assert.ok(!r.includes('right to education'))});
t('búsqueda en vivo: dibuja los resultados de la Biblioteca Digital y escapa el HTML',()=>{const h=run(`vivoHtml('código de conducta',{resultados:[{simbolo:'A/46/558/Corr.2',titulo:'Código <b>x</b>',fecha:'1991-10-24',url:'https://digitallibrary.un.org/record/131830',archivos:[{idioma:'Español',url:'https://digitallibrary.un.org/record/131830/files/A_46_558_Corr.2-ES.pdf'}]}]})`);assert.ok(h.includes('A/46/558/Corr.2')&&h.includes('PDF Español')&&h.includes('sin verificar')&&!h.includes('<b>x</b>'));assert.ok(run(`vivoHtml('zzz',{resultados:[]})`).includes('devolvieron resultados'))});
t('noticias: tarjeta con fecha en español, enlace https y HTML escapado',()=>{const h=run(`noticiaHtml({titulo:'A <i>b</i>',fecha:'2026-10-27',enlace:'https://news.un.org/es/story/1',resumen:'x'})`);assert.ok(h.includes('27 de octubre de 2026')&&h.includes('https://news.un.org/es/story/1')&&!h.includes('<i>b</i>'))});
t('menú y pantalla principal: noticias y DIGNITYOS (aún no lanzado)',()=>{const src=html;assert.ok(src.includes('data-page="noticias"')&&src.includes('data-page="defensores"')&&src.includes('id="homeNoticias"')&&src.includes("showPage('defensores')"));assert.ok(/sin lanzar/.test(src)&&/No lo uses con información real/.test(src))});
