t('hoja de ruta: menú, límite de «Localizado» y enlaces desde las notas',()=>{assert.ok(html.includes('data-page="hojaruta"')&&html.includes('id="hojaruta"')&&html.includes('No sustituye leer el texto')&&(html.match(/showPage\('hojaruta'\)/g)||[]).length>=2)});
