t('menú lateral del celular: margen inferior para llegar al último elemento (no depende de 100vh)',()=>{const m=html.match(/\.side\{position:fixed;top:0;bottom:0;left:0;width:min\(86vw,330px\)[^}]*\}/);assert.ok(m&&!/height:100d?vh/.test(m[0])&&/calc\(110px\+env\(safe-area-inset-bottom\)\)/.test(m[0].replace(/\s/g,'')))});
