t('Siglas: cada entrada tiene inglés, español y explicación; sin duplicados; enlaces internos válidos',()=>{const S=JSON.parse(run('JSON.stringify(SIGS.map(e=>({i:e.id,s:e.sigla,en:e.en,es:e.es,q:e.que,ir:e.ir||""})))'));assert.ok(S.length>=140);assert.equal(new Set(S.map(e=>e.i)).size,S.length);for(const e of S){assert.ok(e.en&&e.es&&e.q.length>20,e.s);if(e.ir)assert.ok(/^[TESMP]:/.test(e.ir),e.s)}const T=JSON.parse(run('JSON.stringify(TRAT.map(t=>t.mtdsg))'));for(const e of S.filter(e=>e.ir.startsWith('T:')))assert.ok(T.includes(e.ir.slice(2)),e.s+' '+e.ir)});
