t('Historia: eventos ordenados, fechas válidas, hitos, temas y enlaces internos válidos',()=>{const H=JSON.parse(run('JSON.stringify(HEV)'));assert.ok(H.length>=50&&H.filter(e=>e.hito).length>=15);for(let i=1;i<H.length;i++)assert.ok(H[i-1].f<=H[i].f,'orden '+H[i].f);const temas=Object.keys(JSON.parse(run('JSON.stringify(HTEMAS)')));for(const e of H){assert.ok(/^\d{4}(-\d{2}(-\d{2})?)?$/.test(e.f)&&temas.includes(e.tema)&&e.t&&e.x.length>30&&e.p.length>20,e.f+' '+e.t);if(e.ir)assert.ok(/^[TESMP]:/.test(e.ir),e.t)}const T=JSON.parse(run('JSON.stringify(TRAT.map(t=>t.mtdsg))'));for(const e of H.filter(e=>(e.ir||'').startsWith('T:')))assert.ok(T.includes(e.ir.slice(2)),e.t);const ents=JSON.parse(run('JSON.stringify(ENT.map(e=>e.id))'));for(const e of H.filter(e=>(e.ir||'').startsWith('E:')))assert.ok(ents.includes(e.ir.slice(2)),e.t+' '+e.ir)});
