t('T59/T60: cita APA en mandato y país; CSV de todos los mandatos y JSON de países',()=>{assert.ok(run("fichaBloques('m',0).map(b=>b.t).join(' ')").includes('Cita APA: Sukima-Labs ('));assert.ok(run("fichaBloques('p','ESP').map(b=>b.t).join(' ')").includes('Tratados de derechos humanos'));assert.equal(run('csvMandatos(D).split("\\r\\n").length'),run('D.length+1'));assert.ok(run('JSON.parse(JSON.stringify({paises:PAISES})).paises.length')>0);run('pintarDescargas()');assert.ok(els.dVersion.textContent.includes('Versión'))});
t('pie de marca: logo, eslogan, correos y sukimalabs.com; GitHub fuera del bloque, código fuente (AGPL) en el sello',()=>{const sf=html.match(/<div class="sidefooter">([\s\S]*?)<\/div><\/aside>/)[1];const pie=html.match(/<div class="pie-sk"[\s\S]*?<footer class="foot">/)[0];for(const b of [sf,pie]){assert.ok(b.includes('class="isotipo-sk"')&&b.includes('El espacio donde nacen nuevas posibilidades')&&b.includes('href="https://sukimalabs.com"')&&b.includes('href="mailto:hola@sukimalabs.com"')&&b.includes('href="mailto:info@sukimalabs.com"')&&!b.includes('github.com'))}assert.ok(sf.includes('Licencia'));assert.ok(/class="sello-autoria"[^]*?href="https:\/\/github.com\/sukima-labs\/atlasonu"/.test(html))});
t('#228: el modo de color se aplica antes de pintar (también en el marco del celular) y hay selector Automático / Claro / Oscuro en la barra y en el menú',()=>{const i=html.indexOf('window.atlasTema=function'),j=html.indexOf('#188: celular con el navegador');assert.ok(i>0&&j>0&&i<j,'el script del modo va antes del marco del celular y de los estilos');assert.ok(i<html.indexOf('<style>'));assert.ok(/localStorage\.getItem\('atlas-tema'\)/.test(html)&&/try\{p=localStorage/.test(html),'lo elegido se guarda en el navegador y funciona sin almacenamiento');assert.ok(/var fc=document\.documentElement\.getAttribute\('data-theme'\)==='light'/.test(html)&&html.includes("e.data.atlas==='tema'"),'el marco del celular sigue el modo');assert.ok(/<select id="temaCel" aria-label="Modo de color"[^>]*>\s*<option value="auto">Automático<\/option><option value="light">Claro<\/option><option value="dark">Oscuro<\/option>/.test(html),'desplegable de la barra superior');assert.ok(/class="tema-sel" role="group" aria-labelledby="temaSelT"/.test(html)&&(html.match(/<button type="button" data-tema="(auto|light|dark)" aria-pressed=/g)||[]).length===3,'botones del menú');assert.ok(/@media print\{@page/.test(html),'la impresión sigue en claro')});
t('marca Sukima Labs v1.1: favicon, icono táctil, isotipo y variables; ATLAS usa la paleta y la letra de la marca (DejaVu Sans incluida, sin peticiones externas)',()=>{for(const f of ['dejavu-sans-regular.woff2','dejavu-sans-bold.woff2','dejavu-sans-regular-arabe.woff2','dejavu-sans-bold-arabe.woff2','LICENSE-DejaVu.txt'])assert.ok(fs.existsSync(path.join(root,'assets','fonts',f)),f);assert.ok(/@font-face\{font-family:"DejaVu Sans"[^}]*font-display:swap;src:url\(assets\/fonts\/dejavu-sans-regular\.woff2\)/.test(html),'@font-face local');assert.ok(!/fonts\.googleapis|fonts\.gstatic|--serif/.test(html),'sin letra externa ni serifa');assert.ok(/--fondo:var\(--sukima-grafito\)/.test(html)&&html.includes('<meta name="theme-color" media="(prefers-color-scheme: dark)" content="#10131C">'),'fondo y theme-color en grafito (modo oscuro)');assert.ok(/html\[data-theme=light\]\{color-scheme:light;\s*--fondo:var\(--sukima-marfil\)/.test(html)&&html.includes('<meta name="theme-color" media="(prefers-color-scheme: light)" content="#F5F4F0">'),'#228: modo claro sobre marfil y su theme-color');for(const f of ['favicon.ico','favicon_16.png','favicon_32.png','apple_touch_icon_180.png','isotipo_color.svg','isotipo_white.svg','brand_tokens.css','brand_tokens.json'])assert.ok(fs.existsSync(path.join(root,'assets','marca',f)),f);assert.ok(html.includes('rel="icon" href="assets/marca/favicon.ico"')&&html.includes('rel="apple-touch-icon" href="assets/marca/apple_touch_icon_180.png"'));assert.ok(html.includes('--sukima-cian:#14C6D4')&&/class="isotipo-sk"[^>]*aria-hidden="true"/.test(html));assert.ok(html.includes('<div class="appbrand">ATLAS <b>ONU</b></div>'));assert.ok(!NOMBRES_FUERA.test(fs.readFileSync(path.join(root,'assets','marca','README.md'),'utf8')))});
t('búsqueda en vivo vacía: sin segundo recuadro de solicitud',()=>{const i=html.indexOf('function vivoHtml(');const f=html.slice(i,html.indexOf('function',i+10));assert.ok(i>0&&!f.includes('solicitudHtml('))});
t('autoría y repositorio',()=>assert.ok(html.includes('sukima-labs/atlasonu')&&html.includes('Sukima-Labs')&&!NOMBRES_FUERA.test(html)));
t('integridad de datos: símbolo localizado ⇒ registro',()=>assert.equal(run('D.flatMap(x=>x.actos).filter(a=>/^VERIFICADO/.test(a.estado)&&!a.registro).length'),0));
t('integridad: ningún DOCUMENTO_NO_RESOLUCION cuenta como localizado',()=>assert.equal(run('D.flatMap(x=>x.actos).filter(a=>a.estado==="DOCUMENTO_NO_RESOLUCION").length'),run('D.reduce((s,x)=>s+x.actos_total-x.actos_verificados,0)')-run('D.flatMap(x=>x.actos).filter(a=>a.estado!=="DOCUMENTO_NO_RESOLUCION"&&!/^VERIFICADO/.test(a.estado)).length')));
t('T63 glosario: reconoce siglas sueltas y alias en español, no dentro de símbolos ni de otras siglas',()=>{const k=run('JSON.stringify(siglasEn("El CEDAW y el EPU; ver A/HRC/RES/5/2, el OP-CAT y el PIDCP. Las ONG."))');assert.deepEqual(JSON.parse(k).map(x=>x.k),['CEDAW','EPU','PIDCP','ONG'],k)});
t('T63 glosario: una sigla con dos sentidos (CAT) da las dos fichas; frases y palabras sueltas no son siglas',()=>{assert.equal(run('SGK.CAT.length'),2);assert.ok(run('!SGK["Views"]&&!SGK["Add."]&&!SGK["UN Women"]&&!SGK["Rev."]'));assert.ok(run('sgHtml("EPU")').includes('Examen Peri'))});
t('T40 relatores: una tarjeta por titular publicado, con mandato y nacionalidad; los mandatos sin titular se listan aparte',()=>{run('renderRel()');const n=run('REL.length');assert.ok(n>=60,'titulares '+n);assert.equal((els.rOut.innerHTML.match(/class="listline rel-card"/g)||[]).length,Math.min(20,n));assert.ok(n<=20||els.rOut.innerHTML.includes('20 de '+n));run('LIM.rel=1000;MASF=1;renderRel();MASF=0');assert.equal((els.rOut.innerHTML.match(/class="listline rel-card"/g)||[]).length,n);run('renderRel()');assert.equal(run('REL.filter(x=>!x.pa).length'),0);assert.equal(run('D.filter(r=>!(r.titulares||[]).length).length')>0,els.rOut.innerHTML.includes('sin titular publicado'))});
t('T40 relatores: filtros por tipo, alcance y tema; buscar por país de nacionalidad en español',()=>{els.rCargo.value='gt';run('renderRel()');assert.ok(!/Relatoría especial<\/span>|Experto\/a independiente<\/span>/.test(els.rOut.innerHTML)&&els.rOut.innerHTML.includes('Grupo de trabajo'));els.rCargo.value='';els.rAlc.value='País';run('renderRel()');assert.equal((els.rOut.innerHTML.match(/rel-card/g)||[]).length,run('REL.filter(x=>x.r.alcance==="País").length'));els.rAlc.value='';run("rSub='tortura';renderRel()");assert.ok(/tortura|detenci/i.test(els.rOut.innerHTML));run("rSub=''");els.rQ.value='Colombia';run('renderRel()');assert.ok(els.rOut.innerHTML.includes('Colombia'));els.rQ.value='';run('renderRel()')});
t('marketing: módulo completo; sin nombres de persona como autoría ni atribución a Claude; marcas de cifras conocidas',()=>{const m=path.join(root,'marketing');const rd=f=>fs.readFileSync(path.join(m,f),'utf8');const todos=[];(function ls(d){for(const e of fs.readdirSync(d,{withFileTypes:true})){const q=path.join(d,e.name);if(e.isDirectory())ls(q);else todos.push(q)}})(m);for(const f of ['README.md','ANALISIS.md','PLAN.md','MENSAJES.md','CANALES.md','REGISTRO.md','cifras.py','kit_prensa/README.md','kit_prensa/CIFRAS.md','contenidos/README.md','metricas/medir.py','metricas/registro.csv'])assert.ok(fs.existsSync(path.join(m,f)),'falta marketing/'+f);const marcas=new Set(['mandatos','actos','localizados','paises','tratados','mecanismos','siglas','historia','entidades','idiomas','fecha']);for(const f of todos){const x=fs.readFileSync(f,'utf8'),r=path.relative(root,f);assert.ok(!NOMBRES_FUERA.test(x),'nombre de persona en '+r);assert.ok(!/Co-Authored-By|Generated with|noreply@anthropic/i.test(x),'atribución a Claude en '+r);for(const k of x.matchAll(/\{\{(\w+)\}\}/g))assert.ok(marcas.has(k[1])||/cifras\.py$/.test(f),'marca desconocida {{'+k[1]+'}} en '+r)}assert.ok(/Sukima-Labs/.test(rd('README.md'))&&/no es un producto oficial/i.test(rd('kit_prensa/README.md')))});
t('variables de diseño: los extremos de la escala del mapa van en #rrggbb (el JS los mezcla) y idiomas.js no lleva colores sueltos',()=>{for(const n of ['--mapa-escala-0','--mapa-escala-9']){const m=html.match(new RegExp(n+':([^;}]+)'));assert.ok(m&&/^#[0-9a-f]{6}$/i.test(m[1].trim()),n+' debe ser #rrggbb')}const js=fs.readFileSync(path.join(root,'assets/idiomas.js'),'utf8');assert.ok(!/#[0-9a-f]{6}\b|#[0-9a-f]{3}\b|rgba?\(/i.test(js),'idiomas.js con colores escritos a mano')});
t('promoción: imagen para compartir 1200x630 con og:image, twitter:card grande, canonical, sitemap y robots',()=>{const png=fs.readFileSync(path.join(root,'assets','social','atlas-onu-og.png'));assert.equal(png.readUInt32BE(16),1200);assert.equal(png.readUInt32BE(20),630);assert.ok(png.length<500000,'imagen demasiado pesada');const u='https://sukimalabs.com/atlasonu/assets/social/atlas-onu-og.png';assert.ok(html.includes('<meta property="og:image" content="'+u+'">')&&html.includes('<meta name="twitter:image" content="'+u+'">')&&html.includes('<meta name="twitter:card" content="summary_large_image">')&&/og:image:alt" content="[^"]{20,}"/.test(html)&&html.includes('rel="canonical" href="https://sukimalabs.com/atlasonu/"'));assert.ok(fs.readFileSync(path.join(root,'sitemap.xml'),'utf8').includes('<loc>https://sukimalabs.com/atlasonu/</loc>')&&/Sitemap: https:\/\/sukimalabs\.com\/atlasonu\/sitemap\.xml/.test(fs.readFileSync(path.join(root,'robots.txt'),'utf8')))});
t('T101: títulos de visitas enteros (sin slice) y errata «independiento» de OHCHR corregida en nuestros nombres',()=>{const h=fs.readFileSync(path.join(root,'index.html'),'utf8');assert.ok(!/x\.t\.replace\(\/\^Report of the \/,''\)\.slice\(/.test(h),'título de visita recortado');const c=JSON.parse(fs.readFileSync(path.join(root,'data','catalogo.json'),'utf8'));const malos=c.mandatos.filter(m=>/independiento/.test(m.nombre+' '+m.tema));assert.equal(malos.length,0,'errata sin corregir');assert.ok(c.mandatos.some(m=>/aquí se corrige la errata/.test(m.observaciones||'')),'falta la nota de la errata')});
console.log(JSON.stringify({success:true,tests:n,mandates:run('D.length'),actos:run('D.reduce((s,x)=>s+x.actos_total,0)'),localizados:run('D.reduce((s,x)=>s+x.actos_verificados,0)')}));
